import itertools, random
from test_reduce import has_hamiltonian_cycle as dp_hc, has_hamiltonian_path as dp_hp

def naive_hc(inst):
    n, edges = inst["n"], inst["edges"]
    if n <= 2: return False
    adj = {u:set() for u in range(n)}
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    for perm in itertools.permutations(range(1,n)):
        o = (0,)+perm
        if all(o[(i+1)%n] in adj[o[i]] for i in range(n)): return True
    return False

def naive_hp(inst):
    n, edges = inst["n"], inst["edges"]
    if n==0: return False
    if n==1: return True
    adj = {u:set() for u in range(n)}
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    for perm in itertools.permutations(range(n)):
        if all(perm[i+1] in adj[perm[i]] for i in range(n-1)): return True
    return False

rng = random.Random(7)
bad=0; tot=0
for _ in range(4000):
    n = rng.randint(0,7)
    pairs=list(itertools.combinations(range(n),2))
    edges=[list(p) for p in pairs if rng.random()<0.4]
    inst={"n":n,"edges":edges}
    tot+=1
    if dp_hc(inst)!=naive_hc(inst) or dp_hp(inst)!=naive_hp(inst):
        bad+=1; print("MISMATCH", inst)
print(f"crosschecked {tot}, mismatches {bad}")
EOF
